css:
.switch {
  font-size: 17px;
  position: relative;
  display: inline-block;
  width: 4em;
  height: 2em;
  border-radius: 30px;
  overflow: hidden;
}

.switch input {
  opacity: 0;
  width: 0;
  height: 0;
}

.slider {
  position: absolute;
  cursor: pointer;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: #ccc;
  transition: 0.4s;
}

.slider:before {
  position: absolute;
  content: "";
  height: 100%;
  width: 0;
  background-color: #d0b0ff;
  transition: 0.4s 0.4s;
}

.slider:after {
  position: absolute;
  content: "";
  height: 1.4em;
  width: 1.4em;
  border-radius: 20px;
  left: 0.3em;
  bottom: 0.3em;
  background-color: #242824;
  transition: 0.4s 0.4s;
  z-index: 10;
}

.switch input:checked + .slider::before {
  width: 100%;
}

.switch input:checked + .slider:after {
  transform: translateX(2em);
  background-color: #9147ff;
}

.switch .hand {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 62px;
  height: 62px;
  transition: 0.4s ease;
}

.switch .hand.left {
  left: -62px;
}

.switch .hand.right {
  right: -62px;
}

.switch .hand.left,
.switch .hand.right {
  animation: none;
}

.switch:focus-within input:checked ~ .hand.right {
  animation: hand-right 0.7s linear;
}

.switch:focus-within input:not(:checked) ~ .hand.left {
  animation: hand-left 0.7s linear;
}

@keyframes hand-left {
  0% {
    left: -62px;
  }
  50% {
    left: 0px;
  }
  100% {
    left: -62px;
  }
}

@keyframes hand-right {
  0% {
    right: -62px;
  }
  50% {
    right: 0px;
  }
  100% {
    right: -62px;
  }
}
